#!/usr/bin/env python3
"""Register inspected inherited anchors and new project claims explicitly."""
import json
from closure_common import ROOT,save,digest

def main():
    sources=json.loads((ROOT/'docs/literature/sources.json').read_text());keyed={s['id']:s for s in sources}
    roles={
      'cluster2021':dict(anchor='Section 3, printed p.10 Assumption 1 (separate exchangeability and dissociation); pp.12--13 Theorems 1--2',supported='Independent multiway sampling premises are distinct from a serially dependent common calendar.',limit='Does not establish the new pair/calendar mixing theorem.'),
      'newey1986':dict(anchor='Printed p.4 / PDF p.6, Theorem 1, Bartlett weights and positive-semidefinite proof; visually inspected original scanned page',supported='Bartlett covariance positive-semidefinite construction; bandwidth and mixing restrictions must accompany inference.',limit='Does not supply a finite-sample coverage guarantee or the new joint sampling argument.'),
      'staiger1994':dict(anchor='Printed p.16 / PDF p.18, exact Gaussian F statement and inversion discussion after Theorem 3; original scan visually inspected',supported='Weak-IV reduced-form null-test inversion can remain valid without a first-stage lower bound under the stated Gaussian exogeneity assumptions.',limit='New scalar quadratic formula and finite information-class invariance are project derivations; general PAG or dependent inference is not inherited.'),
      'dml2018':dict(anchor='Section 4.2, equations (4.5)--(4.8), conditional moments and Robinson partial-linear IV score',supported='Identification moment and orthogonal partial-linear IV score; nuisance product errors matter.',limit='Its iid theorem does not automatically qualify the new dependent fixed-dictionary/QR operation.'),
      'sarkka2013':dict(anchor='Section 12.1, pp.174--176, equations (12.3)--(12.4) and predictive-likelihood factorization',supported='Marginal parameter likelihood integrates latent states and can be evaluated recursively; nonlinear approximation differs from exact Gaussian filtering.',limit='Audit identification, selected16 sandwich and policy-value gradient are project derivations, not general nonlinear qualification.')}
    records=[]
    for key,role in roles.items():
        s=keyed[key];assert digest(s['local_path'])==s['sha256'];records.append(dict(id=key,title=s['title'],version_status=s['version_status'],local_path=s['local_path'],sha256=s['sha256'],**role))
    claims=[
      dict(id='E-R01',claim='Known-inclusion persistent outcome audits, symmetric labels and independent gold validation admit a selected iid-pair/mixing-calendar influence decomposition; finite calibration shortfalls remain.',manuscript_anchor='r8:joint',sources=['cluster2021','newey1986'],evidence_class='project_derivation_and_synthetic_study',artifacts=['src/causalbank/joint_audited.py','docs/studies/reliability-joint-results.json','docs/studies/reliability-followup-results.json','docs/reviews/reliability-independent-algebra.json']),
      dict(id='E-R02',claim='An independent pilot optimizes a declared finite-stratum audit variance objective at matched expected cost; calendar precision and unpriced gold acquisition remain.',manuscript_anchor='r8:audit-design',sources=[],evidence_class='project_derivation_and_synthetic_cost_example',artifacts=['docs/studies/reliability-joint-results.json','tools/reliability_joint_study.py']),
      dict(id='E-R03',claim='Fresh funding calibration separates audit and independently trained response-covariance diagnostics; larger samples and windows do not universally close the gap.',manuscript_anchor='r8:calibration',sources=['newey1986'],evidence_class='synthetic_diagnostic_comparison',artifacts=['docs/studies/reliability-calibration-results.json','tools/reliability_calibration_study.py']),
      dict(id='E-R04',claim='Exact Gaussian sufficient-information and reduced-form weak-IV pivots preserve topology in finite declared latent classes; false restrictions destroy causal coverage.',manuscript_anchor='r8:graphs',sources=['staiger1994'],evidence_class='project_derivation_and_synthetic_study',artifacts=['src/causalbank/gaussian_effect_pivots.py','docs/studies/reliability-graphs-results.json']),
      dict(id='E-R05',claim='Representative state audits identify both action transition variances in a selected16 nonlinear model; local/refinement uncertainty and misspecification availability are explicit.',manuscript_anchor='r8:nonlinear',sources=['sarkka2013'],evidence_class='project_derivation_and_synthetic_study',artifacts=['src/causalbank/nonlinear_variance.py','docs/studies/reliability-nonlinear-results.json','docs/reviews/reliability-independent-algebra.json']),
      dict(id='E-R06',claim='A fixed richer dependent dictionary can fit through chunked QR with dense-equivalent algebra; finite-window coverage, omitted-feature failure and full workload costs remain separate.',manuscript_anchor='r8:learning',sources=['dml2018','newey1986'],evidence_class='project_derivation_and_synthetic_workload',artifacts=['src/causalbank/chunked_learning.py','docs/studies/reliability-learning-results.json','docs/studies/reliability-followup-results.json','docs/studies/reliability-workloads-results.json']),
      dict(id='E-R07',claim='Local route/status/refusal serialization rehearsals and concrete external protocols prepare but do not establish independent, bank, interface, workflow or multi-host acceptance.',manuscript_anchor='r8:external',sources=[],evidence_class='verified_local_rehearsal_and_proposed_external_protocol',artifacts=['src/causalbank/reliability_operations.py','docs/reviews/reliability-local-rehearsal.json','contracts/reliability.md','docs/program/external-validation-v8.md'])]
    path=ROOT/'docs/literature/reconstruction-claims.json';old=json.loads(path.read_text());old=[c for c in old if not c['id'].startswith('E-R')];path.write_text(json.dumps(old+claims,indent=2,ensure_ascii=False)+'\n')
    save('docs/literature/reliability-source-review.json',dict(status='pass',date='2026-10-10',publication_cutoff='2026-10-07',inspected=records,claims=[c['id'] for c in claims],
        search_scope='Reinspection of registered local primary sources. No new search or exhaustive post-cutoff/version/correction clearance claimed.',scope='Primary-source identity and narrow inherited roles; new mathematical integrations are author project derivations.'),['tools/reliability_source_trace.py','docs/literature/sources.json','docs/literature/reconstruction-claims.json']+[r['local_path'] for r in records]+['docs/literature/text/'+k+'.txt' for k in ('cluster2021','dml2018','sarkka2013')])
    print('Registered seven new claim groups and five narrow primary-source roles.')

if __name__=='__main__':main()
